<script setup lang="ts">
import { computed } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'
import { t } from '@/i18n'

const emit = defineEmits<{ (event: 'close'): void }>()

const voiceStore = useVoiceStore()

const masterVolume = computed(() => voiceStore.state.volume)
const peers = computed(() => voiceStore.connectedPeers)

function setMaster(event: Event) {
  voiceStore.setVolume((event.target as HTMLInputElement).valueAsNumber)
}

function setPeer(peerId: string, event: Event) {
  voiceStore.setPeerVolume(peerId, (event.target as HTMLInputElement).valueAsNumber)
}

function percent(volume: number): string {
  return `${Math.round(volume * 100)}%`
}
</script>

<template>
  <section class="mixer-panel" :aria-label="t('mixer.title')">
    <header class="mixer-head">
      <strong>{{ t('mixer.title') }}</strong>
      <button type="button" class="btn btn-icon btn-sm" :aria-label="t('mixer.close')" @click="emit('close')">×</button>
    </header>

    <div class="mixer-row mixer-master">
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
        <polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" />
        <path d="M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07" />
      </svg>
      <span class="mixer-name">{{ t('voice.volume') }}</span>
      <input
        type="range"
        class="mixer-slider"
        :min="0"
        :max="1"
        step="0.01"
        :value="masterVolume"
        :aria-label="t('voice.outputVolumeAria')"
        @input="setMaster"
      />
      <span class="mixer-value">{{ percent(masterVolume) }}</span>
    </div>

    <ul v-if="peers.length" class="mixer-peers">
      <li v-for="peer in peers" :key="peer.peerId" class="mixer-row">
        <span class="mixer-avatar" aria-hidden="true">{{ peer.peerId.slice(0, 2).toUpperCase() }}</span>
        <span class="mixer-name" :title="peer.peerId">
          {{ peer.peerId }}{{ peer.peerId === 'local' ? t('voice.youSuffix') : '' }}
          <span v-if="peer.isMuted" class="mixer-muted" :title="t('voice.mutedBadge')">· {{ t('voice.muted') }}</span>
        </span>
        <input
          type="range"
          class="mixer-slider"
          :min="0"
          :max="1"
          step="0.01"
          :value="peer.volume"
          :aria-label="t('peer.volumeAria', { name: peer.peerId })"
          @input="setPeer(peer.peerId, $event)"
        />
        <span class="mixer-value">{{ percent(peer.volume) }}</span>
      </li>
    </ul>
    <p v-else class="mixer-empty">{{ t('peer.empty') }}</p>
  </section>
</template>

